import { createWall, sortTiles, tileInfo, tileShortLabel, tileClass, tileLabel, isWinningHand, legalClaims, chooseDiscard, removeTiles } from "./game.js";

const STORE = "willow-table-round-v1";
let state;
let botTimer;
const $ = selector => document.querySelector(selector);

function newGame() {
  const wall = createWall();
  const players = Array.from({ length: 4 }, () => ({ hand: [], melds: [], discards: [] }));
  for (let round = 0; round < 13; round++) for (const player of players) player.hand.push(wall.pop());
  players[0].hand.push(wall.pop());
  state = { wall, players, turn: 0, phase: "discard", lastDiscard: null, lastDiscarder: null, message: "Your opening turn. Select a tile to discard.", result: null };
  save(); render();
}
function save() { localStorage.setItem(STORE, JSON.stringify(state)); $("#save-status").textContent = "Saved locally"; }
function load() { try { state = JSON.parse(localStorage.getItem(STORE)); } catch { /* invalid saved state starts anew */ } if (!state?.players?.length) newGame(); else { render(); if (state.phase === "draw" && state.turn !== 0) scheduleBot(); } }
function seatTitle(index) { return ["You · East", "North", "West", "South"][index]; }
function tileHtml(tile, small = false, button = false) {
  const data = tileInfo(tile); const cls = `tile ${small ? "mini-tile" : ""} ${tileClass(tile)}`;
  const body = `<span class="tile-rank">${data.honor ? tileShortLabel(tile) : data.rank}</span><span class="tile-suit">${data.honor ? "honor" : ({m:"char",p:"dots",s:"bamboo"})[data.suit]}</span>`;
  return button ? `<button class="${cls}" data-tile="${tile}" aria-label="Discard ${tileLabel(tile)}">${body}</button>` : `<span class="${cls}" title="${tileLabel(tile)}">${body}</span>`;
}
function renderMelds(melds) { return melds.map(meld => `<span class="meld">${meld.map(tile => tileHtml(tile, true)).join("")}</span>`).join(""); }
function renderOpponent(index) {
  const player = state.players[index]; const el = $(`#seat-${index}`); const active = state.turn === index && state.phase !== "ended";
  el.className = `opponent ${["","east","north","west"][index]} ${active ? "active" : ""}`;
  el.innerHTML = `<div class="seat-heading"><i class="seat-dot"></i><span>${seatTitle(index)} · ${player.hand.length} concealed</span></div><div class="opponent-hand">${Array.from({length:player.hand.length},()=>'<i class="back-tile"></i>').join("")}</div><div class="exposed">${renderMelds(player.melds)}</div><div class="discard-row">${player.discards.slice(-6).map(t=>tileHtml(t,true)).join("")}</div>`;
}
function renderPlayer() {
  const player = state.players[0]; const canDiscard = state.turn === 0 && state.phase === "discard";
  $("#seat-0").innerHTML = `<div class="player-heading"><strong><i class="seat-dot"></i> You · East</strong><span>${player.hand.length} concealed</span></div><div class="exposed">${renderMelds(player.melds)}</div><div class="hand">${sortTiles(player.hand).map(tile=>tileHtml(tile,false,canDiscard)).join("")}</div>`;
  document.querySelectorAll(".hand button[data-tile]").forEach(button => button.addEventListener("click", () => discard(0, button.dataset.tile)));
}
function renderControls() {
  const claim = $("#claim-controls"), turn = $("#turn-controls"); claim.innerHTML = ""; turn.innerHTML = "";
  if (state.phase === "claim" && state.lastDiscard) {
    const claims = legalClaims(state.players[0].hand, state.lastDiscard, (state.lastDiscarder + 1) % 4 === 0, state.players[0].melds.length);
    if (claims.ron) claim.innerHTML += `<button class="action-button warn" data-claim="ron">Ron — win</button>`;
    if (claims.pon) claim.innerHTML += `<button class="action-button" data-claim="pon">Pon</button>`;
    claims.chi.forEach((option,index) => claim.innerHTML += `<button class="action-button" data-claim="chi" data-option="${index}">Chi ${option.map(tileShortLabel).join(" · ")}</button>`);
    claim.innerHTML += `<button class="action-button secondary" data-claim="pass">Pass</button>`;
    claim.querySelectorAll("button").forEach(btn => btn.addEventListener("click", () => userClaim(btn.dataset.claim, btn.dataset.option)));
  }
  if (state.phase === "ended") turn.innerHTML = `<button class="action-button" id="again">Deal a new hand</button>`;
  else if (state.turn !== 0 || state.phase === "draw") turn.innerHTML = `<span class="control-copy">${state.phase === "claim" ? "Waiting for claim decisions…" : "Computer players are thinking…"}</span>`;
  else if (state.phase === "discard") turn.innerHTML = `<span class="control-copy">Your turn — choose a tile to discard.</span>`;
  $("#again")?.addEventListener("click", newGame);
}
function render() {
  for (let i=1;i<4;i++) renderOpponent(i); renderPlayer();
  $("#round-label").textContent = state.result ? "HAND COMPLETE" : `EAST ROUND · ${state.phase === "claim" ? "CLAIM WINDOW" : seatTitle(state.turn).toUpperCase()}`;
  const last = $("#last-discard"); last.className = `last-discard ${state.lastDiscard ? tileClass(state.lastDiscard) : "empty"}`; last.innerHTML = state.lastDiscard ? tileHtml(state.lastDiscard, false) : "—";
  $("#table-message").textContent = state.message; $("#wall-count").textContent = `${state.wall.length} tiles left in wall`; renderControls();
}
function finish(message) { clearTimeout(botTimer); state.phase="ended"; state.result=message; state.message=message; save(); render(); }
function discard(playerIndex, tile) {
  if (state.phase !== "discard" || state.turn !== playerIndex || !state.players[playerIndex].hand.includes(tile)) return;
  state.players[playerIndex].hand = removeTiles(state.players[playerIndex].hand,[tile]); state.players[playerIndex].discards.push(tile);
  state.lastDiscard=tile; state.lastDiscarder=playerIndex; state.phase="claim"; state.message=`${seatTitle(playerIndex)} discarded ${tileLabel(tile)}. Checking claims…`; save(); render();
  if (playerIndex === 0) setTimeout(resolveAfterUserDiscard, 500); else setTimeout(resolveAfterBotDiscard, 500);
}
function availableBotClaimants() {
  const claims=[]; for(let i=1;i<4;i++) { const p=state.players[i]; const legal=legalClaims(p.hand,state.lastDiscard,(state.lastDiscarder+1)%4===i,p.melds.length); if(legal.ron) claims.push({i,type:"ron"}); }
  if(claims.length) return claims; for(let i=1;i<4;i++) if(legalClaims(state.players[i].hand,state.lastDiscard,false).pon) claims.push({i,type:"pon"});
  if(claims.length) return claims; const next=(state.lastDiscarder+1)%4; if(next!==0 && legalClaims(state.players[next].hand,state.lastDiscard,true).chi.length) return [{i:next,type:"chi"}]; return [];
}
function takeClaim(index, type, option) {
  const p=state.players[index], discard=state.lastDiscard; const source=state.players[state.lastDiscarder]; source.discards.pop();
  if(type === "ron") { p.hand.push(discard); finish(`${seatTitle(index)} wins by Ron on ${tileLabel(discard)}.`); return; }
  const used = type === "pon" ? [discard,discard] : option; p.hand=removeTiles(p.hand,used); p.melds.push([...used,discard]); state.turn=index; state.lastDiscard=null; state.phase="discard"; state.message=`${seatTitle(index)} claimed ${type === "pon" ? "Pon" : "Chi"}. ${index===0 ? "Discard a tile." : "They will discard."}`; save(); render(); if(index!==0) scheduleBot();
}
function resolveAfterUserDiscard() { if(state.phase!=="claim") return; const bots=availableBotClaimants(); if(bots.length) { const c=bots[0]; takeClaim(c.i,c.type,c.type==="chi"?legalClaims(state.players[c.i].hand,state.lastDiscard,true).chi[0]:null); } else advanceTurn(); }
function resolveAfterBotDiscard() { if(state.phase!=="claim") return; const claims=legalClaims(state.players[0].hand,state.lastDiscard,(state.lastDiscarder+1)%4===0,state.players[0].melds.length); if(claims.ron||claims.pon||claims.chi.length) { state.message=`${seatTitle(state.lastDiscarder)} discarded ${tileLabel(state.lastDiscard)}. Your claim?`; save(); render(); } else { const bots=availableBotClaimants(); if(bots.length) { const c=bots[0]; takeClaim(c.i,c.type,c.type==="chi"?legalClaims(state.players[c.i].hand,state.lastDiscard,true).chi[0]:null); } else advanceTurn(); } }
function userClaim(type, optionIndex) { if(state.phase!=="claim") return; if(type==="pass") { const bots=availableBotClaimants(); if(bots.length) { const c=bots[0]; takeClaim(c.i,c.type,c.type==="chi"?legalClaims(state.players[c.i].hand,state.lastDiscard,true).chi[0]:null); } else advanceTurn(); return; } const legal=legalClaims(state.players[0].hand,state.lastDiscard,(state.lastDiscarder+1)%4===0,state.players[0].melds.length); if(type==="ron"&&legal.ron) takeClaim(0,"ron"); else if(type==="pon"&&legal.pon) takeClaim(0,"pon"); else if(type==="chi"&&legal.chi[optionIndex]) takeClaim(0,"chi",legal.chi[optionIndex]); }
function advanceTurn() { state.turn=(state.lastDiscarder+1)%4; state.lastDiscard=null; state.phase="draw"; state.message=`${seatTitle(state.turn)} draws a tile.`; save(); render(); if(state.turn===0) drawFor(0); else scheduleBot(); }
function drawFor(index) { if(!state.wall.length) return finish("The wall is exhausted. This hand is a draw."); state.players[index].hand.push(state.wall.pop()); state.phase="discard"; state.message=index===0?"Your turn — choose a tile to discard.":`${seatTitle(index)} is choosing a discard.`; save(); render(); if(index!==0) scheduleBot(); }
function scheduleBot() { clearTimeout(botTimer); botTimer=setTimeout(()=>{ if(state.phase==="draw"&&state.turn!==0) drawFor(state.turn); else if(state.phase==="discard"&&state.turn!==0) { const p=state.players[state.turn]; if(isWinningHand(p.hand,p.melds.length)) finish(`${seatTitle(state.turn)} wins by self-draw.`); else discard(state.turn,chooseDiscard(p.hand)); } },650); }
$("#new-game").addEventListener("click", newGame); load();

import test from "node:test";
import assert from "node:assert/strict";
import { isWinningHand, canRon, canPon, chiOptions, legalClaims, removeTiles } from "./game.js";

const complete = ["1m","2m","3m", "4p","5p","6p", "7s","8s","9s", "E","E","E", "R","R"];

test("recognizes four sets and a pair", () => assert.equal(isWinningHand(complete), true));
test("recognizes a hand with an exposed meld", () => assert.equal(isWinningHand(["1m","2m","3m","4p","5p","6p","E","E","E","R","R"], 1), true));
test("rejects a near-complete non-winning hand", () => assert.equal(isWinningHand([...complete.slice(0,13),"G"]), false));
test("ron requires the discard to make a legal hand", () => { assert.equal(canRon(complete.slice(0,13), "R"), true); assert.equal(canRon(complete.slice(0,13), "G"), false); });
test("pon needs two matching concealed tiles", () => { assert.equal(canPon(["4m","4m","5m"], "4m"), true); assert.equal(canPon(["4m","5m","6m"], "4m"), false); });
test("chi exposes only legal same-suit sequences", () => { assert.deepEqual(chiOptions(["2m","3m","5m","6m"], "4m"), [["2m","3m"],["3m","5m"],["5m","6m"]]); assert.deepEqual(chiOptions(["2m","3m"], "E"), []); });
test("chi is limited to the immediately next player", () => { const hand=["2m","3m"]; assert.equal(legalClaims(hand,"4m",true).chi.length,1); assert.equal(legalClaims(hand,"4m",false).chi.length,0); });
test("removing a claimed duplicate removes exactly two tiles", () => assert.deepEqual(removeTiles(["4m","4m","4m","5m"],["4m","4m"]),["4m","5m"]));

