import { createWall,sortTiles,tileInfo,tileShortLabel,tileClass,tileLabel,isWinningHand,legalClaims,chooseDiscard,removeTiles } from "./game.js";
const STORE="willow-table-round-v1", $=s=>document.querySelector(s);let state,botTimer;
function newGame(){const wall=createWall(),players=Array.from({length:4},()=>({hand:[],melds:[],discards:[]}));for(let r=0;r<13;r++)for(const p of players)p.hand.push(wall.pop());players[0].hand.push(wall.pop());state={wall,players,turn:0,phase:"discard",lastDiscard:null,lastDiscarder:null,message:"Your opening turn. Select a tile to discard.",result:null};save();render()}
function save(){localStorage.setItem(STORE,JSON.stringify(state));$("#save-status").textContent="Saved locally"}function load(){try{state=JSON.parse(localStorage.getItem(STORE))}catch{}if(!state?.players?.length)newGame();else{render();if(state.phase==="draw"&&state.turn!==0)scheduleBot()}}
const seatTitle=i=>["You · East","North","West","South"][i];
function tileHtml(tile,small=false,button=false){const d=tileInfo(tile),cls=`tile ${small?"mini-tile":""} ${tileClass(tile)}`,body=`<span class="tile-rank">${d.honor?tileShortLabel(tile):d.rank}</span><span class="tile-suit">${d.honor?"honor":({m:"char",p:"dots",s:"bamboo"})[d.suit]}</span>`;return button?`<button class="${cls}" data-tile="${tile}" aria-label="Discard ${tileLabel(tile)}">${body}</button>`:`<span class="${cls}" title="${tileLabel(tile)}">${body}</span>`}const melds=m=>m.map(x=>`<span class="meld">${x.map(t=>tileHtml(t,true)).join("")}</span>`).join("");
function renderOpponent(i){const p=state.players[i],el=$(`#seat-${i}`),active=state.turn===i&&state.phase!=="ended";el.className=`opponent ${["","east","north","west"][i]} ${active?"active":""}`;el.innerHTML=`<div class="seat-heading"><i class="seat-dot"></i><span>${seatTitle(i)} · ${p.hand.length} concealed</span></div><div class="opponent-hand">${Array.from({length:p.hand.length},()=>'<i class="back-tile"></i>').join("")}</div><div class="exposed">${melds(p.melds)}</div><div class="discard-row">${p.discards.slice(-6).map(t=>tileHtml(t,true)).join("")}</div>`}
function renderPlayer(){const p=state.players[0],can=state.turn===0&&state.phase==="discard";$("#seat-0").innerHTML=`<div class="player-heading"><strong><i class="seat-dot"></i> You · East</strong><span>${p.hand.length} concealed</span></div><div class="exposed">${melds(p.melds)}</div><div class="hand">${sortTiles(p.hand).map(t=>tileHtml(t,false,can)).join("")}</div>`;document.querySelectorAll(".hand button[data-tile]").forEach(b=>b.onclick=()=>discard(0,b.dataset.tile))}
function render(){for(let i=1;i<4;i++)renderOpponent(i);renderPlayer();$("#round-label").textContent=state.result?"HAND COMPLETE":`EAST ROUND · ${state.phase==="claim"?"CLAIM WINDOW":seatTitle(state.turn).toUpperCase()}`;const last=$("#last-discard");last.className=`last-discard ${state.lastDiscard?tileClass(state.lastDiscard):"empty"}`;last.innerHTML=state.lastDiscard?tileHtml(state.lastDiscard):"—";$("#table-message").textContent=state.message;$("#wall-count").textContent=`${state.wall.length} tiles left in wall`;renderControls()}
/* APPEND */

function renderControls(){const claim=$("#claim-controls"),turn=$("#turn-controls");claim.innerHTML="";turn.innerHTML="";if(state.phase==="claim"&&state.lastDiscard){const c=legalClaims(state.players[0].hand,state.lastDiscard,(state.lastDiscarder+1)%4===0,state.players[0].melds.length);if(c.ron)claim.innerHTML+='<button class="action-button warn" data-claim="ron">Ron — win</button>';if(c.pon)claim.innerHTML+='<button class="action-button" data-claim="pon">Pon</button>';c.chi.forEach((o,i)=>claim.innerHTML+=`<button class="action-button" data-claim="chi" data-option="${i}">Chi ${o.map(tileShortLabel).join(" · ")}</button>`);claim.innerHTML+='<button class="action-button secondary" data-claim="pass">Pass</button>';claim.querySelectorAll("button").forEach(b=>b.onclick=()=>userClaim(b.dataset.claim,b.dataset.option))}if(state.phase==="ended")turn.innerHTML='<button class="action-button" id="again">Deal a new hand</button>';else if(state.turn!==0||state.phase==="draw")turn.innerHTML=`<span class="control-copy">${state.phase==="claim"?"Waiting for claim decisions…":"Computer players are thinking…"}</span>`;else if(state.phase==="discard")turn.innerHTML='<span class="control-copy">Your turn — choose a tile to discard.</span>';$("#again")?.addEventListener("click",newGame)}
function finish(msg){clearTimeout(botTimer);state.phase="ended";state.result=msg;state.message=msg;save();render()}
function discard(i,tile){if(state.phase!=="discard"||state.turn!==i||!state.players[i].hand.includes(tile))return;const p=state.players[i];p.hand=removeTiles(p.hand,[tile]);p.discards.push(tile);state.lastDiscard=tile;state.lastDiscarder=i;state.phase="claim";state.message=`${seatTitle(i)} discarded ${tileLabel(tile)}. Checking claims…`;save();render();setTimeout(i===0?resolveAfterUserDiscard:resolveAfterBotDiscard,500)}
function botClaimants(){const out=[];for(let i=1;i<4;i++){const p=state.players[i],c=legalClaims(p.hand,state.lastDiscard,(state.lastDiscarder+1)%4===i,p.melds.length);if(c.ron)out.push({i,type:"ron"})}if(out.length)return out;for(let i=1;i<4;i++)if(legalClaims(state.players[i].hand,state.lastDiscard,false).pon)out.push({i,type:"pon"});if(out.length)return out;const next=(state.lastDiscarder+1)%4;if(next!==0&&legalClaims(state.players[next].hand,state.lastDiscard,true).chi.length)return[{i:next,type:"chi"}];return out}
function takeClaim(i,type,option){const p=state.players[i],d=state.lastDiscard;state.players[state.lastDiscarder].discards.pop();if(type==="ron"){p.hand.push(d);finish(`${seatTitle(i)} wins by Ron on ${tileLabel(d)}.`);return}const used=type==="pon"?[d,d]:option;p.hand=removeTiles(p.hand,used);p.melds.push([...used,d]);state.turn=i;state.lastDiscard=null;state.phase="discard";state.message=`${seatTitle(i)} claimed ${type==="pon"?"Pon":"Chi"}. ${i===0?"Discard a tile.":"They will discard."}`;save();render();if(i!==0)scheduleBot()}
function resolveAfterUserDiscard(){if(state.phase!=="claim")return;const bots=botClaimants();if(bots.length){const c=bots[0];takeClaim(c.i,c.type,c.type==="chi"?legalClaims(state.players[c.i].hand,state.lastDiscard,true).chi[0]:null)}else advanceTurn()}
function resolveAfterBotDiscard(){if(state.phase!=="claim")return;const c=legalClaims(state.players[0].hand,state.lastDiscard,(state.lastDiscarder+1)%4===0,state.players[0].melds.length);if(c.ron||c.pon||c.chi.length){state.message=`${seatTitle(state.lastDiscarder)} discarded ${tileLabel(state.lastDiscard)}. Your claim?`;save();render()}else resolveAfterUserDiscard()}

function userClaim(type,option){if(state.phase!=="claim")return;if(type==="pass")return resolveAfterUserDiscard();const c=legalClaims(state.players[0].hand,state.lastDiscard,(state.lastDiscarder+1)%4===0,state.players[0].melds.length);if(type==="ron"&&c.ron)takeClaim(0,"ron");else if(type==="pon"&&c.pon)takeClaim(0,"pon");else if(type==="chi"&&c.chi[option])takeClaim(0,"chi",c.chi[option])}
function advanceTurn(){state.turn=(state.lastDiscarder+1)%4;state.lastDiscard=null;state.phase="draw";state.message=`${seatTitle(state.turn)} draws a tile.`;save();render();if(state.turn===0)drawFor(0);else scheduleBot()}
function drawFor(i){if(!state.wall.length)return finish("The wall is exhausted. This hand is a draw.");state.players[i].hand.push(state.wall.pop());state.phase="discard";state.message=i===0?"Your turn — choose a tile to discard.":`${seatTitle(i)} is choosing a discard.`;save();render();if(i!==0)scheduleBot()}
function scheduleBot(){clearTimeout(botTimer);botTimer=setTimeout(()=>{if(state.phase==="draw"&&state.turn!==0)drawFor(state.turn);else if(state.phase==="discard"&&state.turn!==0){const p=state.players[state.turn];if(isWinningHand(p.hand,p.melds.length))finish(`${seatTitle(state.turn)} wins by self-draw.`);else discard(state.turn,chooseDiscard(p.hand))}},650)}
