101 | /** Returns all legal two-tile combinations in a hand that form a chi with a discard. */
102 | export function chiOptions(hand, discard) {
103 |   const { suit, rank, honor } = tileInfo(discard);
104 |   if (honor) return [];
105 |   const options = [];
106 |   for (const [a, b] of [[rank - 2, rank - 1], [rank - 1, rank + 1], [rank + 1, rank + 2]]) {
107 |     if (a < 1 || b > 9) continue;
108 |     const first = `${a}${suit}`, second = `${b}${suit}`;
109 |     const available = [...hand];
110 |     const one = available.indexOf(first); if (one < 0) continue;
111 |     available.splice(one, 1);
112 |     if (available.includes(second)) options.push([first, second]);
113 |   }
114 |   return options;
115 | }
