121 | export function chooseDiscard(hand) {
122 |   const counts = countsFor(hand);
123 |   const isolated = hand.filter(tile => {
124 |     const { suit, rank, honor } = tileInfo(tile);
125 |     if (honor) return counts.get(tile) === 1;
