import { isWinningHand, legalClaims, removeTiles } from "./game.js";

const priority = { ron: 3, pon: 2, chi: 1 };
export const nextSeat = seat => (seat + 1) % 4;
export const seatDistance = (from, to) => (to - from + 4) % 4;

export function canSelfDraw(state, seat = state.turn) {
  const player = state.players[seat];
  return state.phase === "discard" && state.turn === seat && isWinningHand(player.hand, player.melds.length);
}

/** Returns this seat's legal choices. The discarder is never a claimant. */
export function claimChoices(state, seat) {
  if (state.phase !== "claim" || !state.lastDiscard || seat === state.lastDiscarder) return { ron: false, pon: false, chi: [] };
  const player = state.players[seat];
  return legalClaims(player.hand, state.lastDiscard, nextSeat(state.lastDiscarder) === seat, player.melds.length);
}

/** A computer always elects its highest legal claim; userChoice is optional. */
export function claimCandidates(state, userChoice = null) {
  if (state.phase !== "claim" || !state.lastDiscard) return [];
  const candidates = [];
  for (let seat = 0; seat < state.players.length; seat++) {
    if (seat === state.lastDiscarder) continue;
    const choices = claimChoices(state, seat);
    const requested = seat === 0 ? userChoice : (choices.ron ? "ron" : choices.pon ? "pon" : choices.chi.length ? "chi" : null);
    if (!requested || !choices[requested] || (requested === "chi" && !choices.chi.length)) continue;
    candidates.push({ seat, type: requested, tiles: requested === "chi" ? choices.chi[userChoice?.option ?? 0] : null });
  }
  return candidates;
}

/** Higher claim type wins. Equal types are won by the closest seat after the discarder. */
export function chooseClaim(state, candidates) {
  return [...candidates].sort((a, b) => priority[b.type] - priority[a.type] || seatDistance(state.lastDiscarder, a.seat) - seatDistance(state.lastDiscarder, b.seat))[0] || null;
}

export function settleClaims(state, userChoice = null) {
  const winner = chooseClaim(state, claimCandidates(state, userChoice));
  return winner ? { kind: "claim", ...winner } : { kind: "advance", seat: nextSeat(state.lastDiscarder) };
}

export function applySettlement(state, settlement) {
  const next = structuredClone(state);
  if (settlement.kind === "advance") {
    next.turn = settlement.seat; next.lastDiscard = null; next.phase = "draw";
    return next;
  }
  const claimant = next.players[settlement.seat];
  const source = next.players[next.lastDiscarder];
  const discard = next.lastDiscard;
  source.discards.pop();
  if (settlement.type === "ron") {
    claimant.hand.push(discard); next.phase = "ended"; next.result = `Seat ${settlement.seat} wins by Ron.`;
    return next;
  }
  const used = settlement.type === "pon" ? [discard, discard] : settlement.tiles;
  claimant.hand = removeTiles(claimant.hand, used);
  claimant.melds.push([...used, discard]); next.turn = settlement.seat; next.lastDiscard = null; next.phase = "discard";
  return next;
}

export function discardTransition(state, seat, tile) {
  if (state.phase !== "discard" || state.turn !== seat || !state.players[seat].hand.includes(tile)) return null;
  const next = structuredClone(state); const player = next.players[seat];
  player.hand = removeTiles(player.hand, [tile]); player.discards.push(tile);
  next.lastDiscard = tile; next.lastDiscarder = seat; next.phase = "claim";
  return next;
}

export function drawTransition(state) {
  if (state.phase !== "draw") return null;
  const next = structuredClone(state);
  if (!next.wall.length) { next.phase = "ended"; next.result = "The wall is exhausted. This hand is a draw."; return next; }
  next.players[next.turn].hand.push(next.wall.pop()); next.phase = "discard";
  return next;
}

