  const state=pending({discarder:0,hands:[["4m","4m","4m"],[],[],[]]});
  assert.deepEqual(claimChoices(state,0),{ron:false,pon:false,chi:[]});
  assert.equal(settleClaims(state).kind,"advance");
});
