12 | /** Returns this seat's legal choices. The discarder is never a claimant. */
13 | export function claimChoices(state, seat) {
14 |   if (state.phase !== "claim" || !state.lastDiscard || seat === state.lastDiscarder) return { ron: false, pon: false, chi: [] };
15 |   const player = state.players[seat];
16 |   return legalClaims(player.hand, state.lastDiscard, nextSeat(state.lastDiscarder) === seat, player.melds.length);
17 | }
