19 | /** A computer always elects its highest legal claim; userChoice is optional. */
20 | export function claimCandidates(state, userChoice = null) {
21 |   if (state.phase !== "claim" || !state.lastDiscard) return [];
22 |   const candidates = [];
23 |   for (let seat = 0; seat < state.players.length; seat++) {
24 |     if (seat === state.lastDiscarder) continue;
25 |     const choices = claimChoices(state, seat);
26 |     const requested = seat === 0 ? userChoice?.type : (choices.ron ? "ron" : choices.pon ? "pon" : choices.chi.length ? "chi" : null);
27 |     if (!requested || !choices[requested] || (requested === "chi" && !choices.chi.length)) continue;
28 |     candidates.push({ seat, type: requested, tiles: requested === "chi" ? choices.chi[userChoice?.option ?? 0] : null });
29 |   }
30 |   return candidates;
31 | }
