33 | /** Higher claim type wins. Equal types are won by the closest seat after the discarder. */
34 | export function chooseClaim(state, candidates) {
35 |   return [...candidates].sort((a, b) => priority[b.type] - priority[a.type] || seatDistance(state.lastDiscarder, a.seat) - seatDistance(state.lastDiscarder, b.seat))[0] || null;
36 | }
