38 | export function settleClaims(state, userChoice = null) {
39 |   const winner = chooseClaim(state, claimCandidates(state, userChoice));
40 |   return winner ? { kind: "claim", ...winner } : { kind: "advance", seat: nextSeat(state.lastDiscarder) };
41 | }
