43 | export function applySettlement(state, settlement) {
44 |   const next = structuredClone(state);
45 |   if (settlement.kind === "advance") {
46 |     next.turn = settlement.seat; next.lastDiscard = null; next.phase = "draw";
47 |     return next;
48 |   }
49 |   const claimant = next.players[settlement.seat];
50 |   const source = next.players[next.lastDiscarder];
51 |   const discard = next.lastDiscard;
52 |   source.discards.pop();
53 |   if (settlement.type === "ron") {
