 81 | /** A winning concealed portion is four melds plus a pair after accounting for exposed melds. */
 82 | export function isWinningHand(tiles, exposedMelds = 0) {
 83 |   const needed = 14 - exposedMelds * 3;
 84 |   if (tiles.length !== needed) return false;
 85 |   const counts = countsFor(tiles);
 86 |   for (const [tile, count] of counts) {
 87 |     if (count < 2) continue;
 88 |     counts.set(tile, count - 2);
 89 |     if (canCompleteMelds(counts, needed - 2)) { counts.set(tile, count); return true; }
 90 |     counts.set(tile, count);
 91 |   }
 92 |   return false;
 93 | }
